def write_online_with_retry(redis_client, key, mapping, retries=3):
    for attempt in range(retries):
        try:
            pipe = redis_client.pipeline(transaction=False)
            pipe.hset(key, mapping=mapping)
            pipe.expire(key, 86400 * 7)
            return pipe.execute()
        except RedisError:
            if attempt == retries - 1:
                dead_letter_queue.publish(key, mapping)
            time.sleep(0.02 * (2 ** attempt))

async def fetch_features(entities, timeout_ms=4.0):
    try:
        return await asyncio.wait_for(
            redis_pool.mget([f'fv:v2:{e}' for e in entities]),
            timeout=timeout_ms / 1000.0
        )
    except asyncio.TimeoutError:
        metrics.inc('feature_store.online_timeout')
        return [DEFAULT_FEATURE_VECTOR for _ in entities]

def compute_on_demand(req_amount, online_vec):
    avg_30d = max(online_vec.get('avg_spend_30d', 1.0), 1e-6)
    return {'spend_ratio': round(req_amount / avg_30d, 4)}

def check_psi(expected_hist, actual_hist, threshold=0.2):
    psi = sum((a - e) * math.log((a + 1e-6) / (e + 1e-6)) for e, a in zip(expected_hist, actual_hist))
    if psi > threshold:
        alert_pagerduty('FeatureDriftDetected', psi=round(psi, 4))
    return psi
